from pathlib import Path
import json,urllib.request,datetime,hashlib,subprocess,concurrent.futures,re
p=Path.cwd();(p/'sources').mkdir(exist_ok=True);r=json.loads((p/'reservation.json').read_text())
urls=[('registry-'+str(j),'https://github.com/'+s) for j,s in enumerate(['openai/math','LeanPool/lean-pool','TauCetiProject/TauCeti','google-deepmind/formal-conjectures'])]
urls+=list(dict.fromkeys((x['source_url'].rsplit('/',1)[1],'https://arxiv.org/pdf/'+x['source_url'].rsplit('/',1)[1]) for x in r['rows']))
def fetch(item):
 name,url=item;d={'url':url,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'name':name,'depth':'acquisition only'}
 try:
  with urllib.request.urlopen(url,timeout=16) as z:b=z.read();d.update(status=z.status,finalURL=z.url,bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
  ext='pdf' if b.startswith(b'%PDF') else 'html';f=p/'sources'/(name+'.'+ext);f.write_bytes(b);d['file']=str(f.relative_to(p))
  if ext=='pdf':
   q=subprocess.run(['pdftotext','-layout',str(f),str(f.with_suffix('.txt'))],capture_output=True,timeout=12);d['converter_exit']=q.returncode
  else:d['heads']=list(dict.fromkeys(re.findall(r'"currentOid":"([a-f0-9]{40})"',b.decode(errors='replace'))))
 except Exception as e:d['error']=str(e)
 return d
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as ex:out=list(ex.map(fetch,urls))
